/**
 * CLAUDE.md non-negotiable 6: training tasks and outcome tests are separate modules with separate
 * stimuli; outcome tests are never generated by training code. Enforced on imports.
 */
import { readFileSync, readdirSync } from "node:fs";
import { describe, expect, it } from "vitest";

const SRC = new URL("../../", import.meta.url);
const read = (rel: string) => readFileSync(new URL(rel, SRC), "utf8");

/** Value (non-type) import specifiers of a TypeScript source. */
function valueImports(src: string): string[] {
  const out: string[] = [];
  for (const m of src.matchAll(/^import\s+(type\s+)?[^;]*?from\s+"([^"]+)";/gms)) if (!m[1]) out.push(m[2]);
  return out;
}

const TRAINING = ["curriculum", "curriculum-sim", "block-runner", "trial", "layout", "frame-patches", "results"];
const outcomeCore = readdirSync(new URL("core/outcome/", SRC)).filter((f) => f.endsWith(".ts") && !f.endsWith(".test.ts"));
const outcomeScreens = readdirSync(new URL("app/screens/", SRC)).filter((f) => f.startsWith("outcome"));

describe("outcome tests are separate from training", () => {
  it("outcome modules import no training-engine values", () => {
    expect(outcomeCore.length).toBeGreaterThanOrEqual(5);
    expect(outcomeScreens.length).toBeGreaterThanOrEqual(1);
    const files = [...outcomeCore.map((f) => `core/outcome/${f}`), ...outcomeScreens.map((f) => `app/screens/${f}`)];
    for (const f of files) {
      for (const spec of valueImports(read(f))) {
        const base = spec.split("/").pop()!;
        expect(TRAINING, `${f} imports ${spec}`).not.toContain(base);
        expect(spec, `${f} imports ${spec}`).not.toMatch(/screens\/train$/);
      }
    }
  });

  it("training modules import nothing from the outcome tests", () => {
    const files = [...TRAINING.map((t) => `core/${t}.ts`), "app/screens/train.ts"];
    for (const f of files) expect(read(f), f).not.toMatch(/from\s+"[^"]*outcome/);
  });
});
